  (1662, '5. Уровень B1', 'Выражения и связки', 'at least', 'по крайней мере, как минимум', 'ən azı, heç olmasa', 'You should sleep at least eight hours.', '/ət ˈliːst/', 'phrase', ''),
  (1663, '5. Уровень B1', 'Выражения и связки', 'even if', 'даже если', 'hətta ... olsa belə', 'I''ll go even if it rains.', '/ˌiːvn ˈɪf/', 'conjunction', ''),
  (1664, '5. Уровень B1', 'Выражения и связки', 'as long as', 'при условии что, пока', 'şərtilə ki, nə qədər ki', 'You can borrow my car as long as you drive carefully.', '/əz ˈlɒŋ əz/', 'conjunction', ''),
  (1665, '5. Уровень B1', 'Выражения и связки', 'in case', 'на случай если', 'hər ehtimala qarşı, ... olar deyə', 'Take an umbrella in case it rains.', '/ɪn ˈkeɪs/', 'conjunction', ''),
  (1666, '5. Уровень B1', 'Выражения и связки', 'apart from', 'кроме, помимо', '... başqa, ... savayı', 'Apart from Ali, everyone came to the party.', '/əˈpɑːt frəm/', 'preposition', ''),
  (1667, '5. Уровень B1', 'Выражения и связки', 'as well as', 'а также, так же как и', '... ilə yanaşı, həmçinin', 'She speaks French as well as English.', '/əz ˈwel əz/', 'conjunction', ''),
  (1668, '5. Уровень B1', 'Выражения и связки', 'due to', 'из-за, вследствие', '... səbəbindən, ... görə', 'The flight was cancelled due to bad weather.', '/ˈdjuː tə/', 'preposition', ''),
  (1669, '5. Уровень B1', 'Выражения и связки', 'in spite of', 'несмотря на', '... baxmayaraq', 'We enjoyed the trip in spite of the rain.', '/ɪn ˈspaɪt əv/', 'preposition', ''),
  (1670, '5. Уровень B1', 'Выражения и связки', 'in other words', 'другими словами', 'başqa sözlə', 'He''s always late. In other words, you can''t rely on him.', '/ɪn ˈʌðə wɜːdz/', 'phrase', ''),
  (1671, '5. Уровень B1', 'Выражения и связки', 'after all', 'в конце концов, всё-таки', 'axı, nəhayət', 'Don''t be angry with him. After all, he''s only a child.', '/ˌɑːftər ˈɔːl/', 'phrase', ''),
  (1672, '5. Уровень B1', 'Выражения и связки', 'on the whole', 'в целом', 'ümumilikdə, bütövlükdə', 'On the whole, the trip was a success.', '/ɒn ðə ˈhəʊl/', 'phrase', ''),
  (1673, '5. Уровень B1', 'Выражения и связки', 'what''s more', 'более того', 'üstəlik', 'The hotel was cheap, and what''s more, it was very clean.', '/ˌwɒts ˈmɔː(r)/', 'phrase', ''),
  (1674, '5. Уровень B1', 'Выражения и связки', 'meanwhile', 'тем временем', 'bu arada, həmin vaxt', 'I cooked dinner. Meanwhile, my husband cleaned the flat.', '/ˈmiːnwaɪl/', 'adverb', ''),
  (1675, '5. Уровень B1', 'Выражения и связки', 'either ... or', 'или ... или', 'ya ... ya da', 'You can either call me or send a message.', '/ˈaɪðə ɔː(r)/', 'conjunction', ''),
  (1676, '5. Уровень B1', 'Выражения и связки', 'neither ... nor', 'ни ... ни', 'nə ... nə də', 'Neither my brother nor my sister can swim.', '/ˈnaɪðə nɔː(r)/', 'conjunction', ''),
  (1677, '5. Уровень B1', 'Выражения и связки', 'sooner or later', 'рано или поздно', 'gec-tez', 'Sooner or later you will find a good job.', '/ˌsuːnər ɔː ˈleɪtə(r)/', 'phrase', ''),
  (1678, '5. Уровень B1', 'Выражения и связки', 'on purpose', 'нарочно, специально', 'qəsdən, bilərəkdən', 'I didn''t break the glass on purpose.', '/ɒn ˈpɜːpəs/', 'phrase', ''),
  (1679, '5. Уровень B1', 'Выражения и связки', 'in advance', 'заранее', 'əvvəlcədən', 'You should book tickets in advance.', '/ɪn ədˈvɑːns/', 'phrase', '');
insert into public.ielts_bank (position, course, topic, word, translation_ru, translation_az, example, ipa, pos, synonyms) values
  (10001, '2. IELTS B1+', 'Образование', 'tuition fees', 'плата за обучение', 'təhsil haqqı', 'Many students in Baku work part-time to pay their tuition fees.', '/tjuˈɪʃn fiːz/', 'collocation', ''),
  (10002, '2. IELTS B1+', 'Образование', 'higher education', 'высшее образование', 'ali təhsil', 'Higher education should be free for talented students.', '/ˌhaɪər edʒuˈkeɪʃn/', 'collocation', ''),
  (10003, '2. IELTS B1+', 'Образование', 'curriculum', 'учебная программа', 'tədris proqramı, kurikulum', 'The school curriculum should include more practical skills.', '/kəˈrɪkjələm/', 'noun', ''),
  (10004, '2. IELTS B1+', 'Образование', 'critical thinking', 'критическое мышление', 'tənqidi təfəkkür', 'Schools should teach critical thinking, not just facts.', '/ˌkrɪtɪkl ˈθɪŋkɪŋ/', 'collocation', ''),
  (10005, '2. IELTS B1+', 'Образование', 'distance learning', 'дистанционное обучение', 'distant təhsil, məsafədən təhsil', 'Distance learning became very popular during the pandemic.', '/ˈdɪstəns ˌlɜːnɪŋ/', 'collocation', ''),
  (10006, '2. IELTS B1+', 'Образование', 'state school', 'государственная школа', 'dövlət məktəbi', 'Most children in my country go to state schools.', '/ˈsteɪt skuːl/', 'collocation', ''),
  (10007, '2. IELTS B1+', 'Образование', 'drop out', 'бросить учёбу', 'təhsili yarımçıq qoymaq', 'Some students drop out of university because of money problems.', '/ˌdrɒp ˈaʊt/', 'phrasal verb', ''),
  (10008, '2. IELTS B1+', 'Образование', 'undergraduate', 'студент бакалавриата', 'bakalavr tələbəsi', 'She is an undergraduate at Baku State University.', '/ˌʌndəˈɡrædʒuət/', 'noun', ''),
  (10009, '2. IELTS B1+', 'Образование', 'postgraduate', 'магистерский, аспирантский (после бакалавриата)', 'magistratura, magistr', 'He wants to do a postgraduate course in the UK.', '/ˌpəʊstˈɡrædʒuət/', 'adjective', ''),
  (10010, '2. IELTS B1+', 'Образование', 'enrol', 'поступать, записываться (на курс)', 'qeydiyyatdan keçmək, daxil olmaq', 'More adults are enrolling on evening courses.', '/ɪnˈrəʊl/', 'verb', ''),
  (10011, '2. IELTS B1+', 'Образование', 'academic performance', 'успеваемость', 'akademik göstəricilər, təhsil nəticələri', 'Lack of sleep can harm a student''s academic performance.', '/ˌækəˈdemɪk pəˈfɔːməns/', 'collocation', ''),
  (10012, '2. IELTS B1+', 'Образование', 'vocational training', 'профессиональное обучение', 'peşə təhsili', 'Vocational training prepares young people for practical jobs.', '/vəʊˈkeɪʃənl ˈtreɪnɪŋ/', 'collocation', ''),
  (10013, '2. IELTS B1+', 'Образование', 'private tutoring', 'частные уроки, репетиторство', 'fərdi dərslər, repetitorluq', 'Private tutoring is very common before university entrance exams.', '/ˌpraɪvət ˈtjuːtərɪŋ/', 'collocation', ''),
  (10014, '2. IELTS B1+', 'Образование', 'extracurricular activities', 'внеклассные занятия', 'dərsdənkənar fəaliyyətlər', 'Extracurricular activities help children develop social skills.', '/ˌekstrəkəˈrɪkjələr ækˈtɪvətiz/', 'collocation', ''),
  (10015, '2. IELTS B1+', 'Образование', 'discipline', 'дисциплина', 'nizam-intizam', 'It is difficult for teachers to keep discipline in large classes.', '/ˈdɪsəplɪn/', 'noun', ''),
  (10016, '2. IELTS B1+', 'Образование', 'literacy', 'грамотность', 'savadlılıq', 'Digital literacy is as important as reading and writing today.', '/ˈlɪtərəsi/', 'noun', ''),
  (10017, '2. IELTS B1+', 'Образование', 'gap year', 'год перерыва (перед университетом)', 'fasilə ili (universitetdən əvvəl)', 'Taking a gap year can help young people become more independent.', '/ˈɡæp jɪə/', 'collocation', ''),
  (10018, '2. IELTS B1+', 'Образование', 'attendance', 'посещаемость', 'davamiyyət', 'Attendance at lectures is compulsory at many universities.', '/əˈtendəns/', 'noun', ''),
  (10019, '2. IELTS B1+', 'Образование', 'well-educated', 'образованный', 'savadlı, yaxşı təhsil almış', 'A well-educated workforce helps the economy grow.', '/ˌwel ˈedʒukeɪtɪd/', 'adjective', ''),
  (10020, '2. IELTS B1+', 'Образование', 'lifelong learning', 'обучение в течение всей жизни', 'ömürboyu təhsil', 'Lifelong learning is necessary because technology changes so fast.', '/ˌlaɪflɒŋ ˈlɜːnɪŋ/', 'collocation', ''),
  (10021, '2. IELTS B1+', 'Образование', 'specialise in', 'специализироваться на', 'ixtisaslaşmaq', 'She decided to specialise in computer science.', '/ˈspeʃəlaɪz ɪn/', 'verb', ''),
  (10022, '2. IELTS B1+', 'Образование', 'hands-on', 'практический', 'praktiki, təcrübəyə əsaslanan', 'Children learn better through hands-on activities.', '/ˌhændz ˈɒn/', 'adjective', ''),
  (10023, '2. IELTS B1+', 'Образование', 'syllabus', 'программа курса', 'tədris planı, sillabus', 'The syllabus covers grammar, reading and writing.', '/ˈsɪləbəs/', 'noun', ''),
  (10024, '2. IELTS B1+', 'Образование', 'rote learning', 'зубрёжка', 'əzbərçilik', 'Rote learning does not help students understand the subject.', '/ˌrəʊt ˈlɜːnɪŋ/', 'collocation', ''),
  (10025, '2. IELTS B1+', 'Образование', 'plagiarism', 'плагиат', 'plagiat', 'Universities treat plagiarism as a serious offence.', '/ˈpleɪdʒərɪzəm/', 'noun', ''),
  (10026, '2. IELTS B1+', 'Образование', 'pre-school', 'дошкольный', 'məktəbəqədər', 'Pre-school education helps children get ready for primary school.', '/ˈpriːskuːl/', 'adjective', ''),
  (10027, '2. IELTS B1+', 'Образование', 'mature student', 'взрослый студент', 'yaşlı tələbə, yetkin yaşda tələbə', 'As a mature student, he studies and works at the same time.', '/məˌtʃʊə ˈstjuːdnt/', 'collocation', ''),
  (10028, '2. IELTS B1+', 'Образование', 'single-sex school', 'школа раздельного обучения', 'oğlan və ya qız məktəbi', 'Some parents prefer single-sex schools for their daughters.', '/ˌsɪŋɡl ˈseks skuːl/', 'collocation', ''),
  (10029, '2. IELTS B1+', 'Работа и карьера', 'work-life balance', 'баланс работы и личной жизни', 'iş və şəxsi həyat balansı', 'A good work-life balance is more important to me than a high salary.', '/ˌwɜːk ˈlaɪf ˌbæləns/', 'collocation', ''),
  (10030, '2. IELTS B1+', 'Работа и карьера', 'job satisfaction', 'удовлетворённость работой', 'işdən məmnunluq', 'Job satisfaction often depends on good relationships with colleagues.', '/ˈdʒɒb sætɪsˌfækʃn/', 'collocation', ''),
  (10031, '2. IELTS B1+', 'Работа и карьера', 'workload', 'рабочая нагрузка', 'iş yükü', 'Teachers often complain about their heavy workload.', '/ˈwɜːkləʊd/', 'noun', ''),
  (10032, '2. IELTS B1+', 'Работа и карьера', 'working hours', 'рабочие часы, рабочее время', 'iş saatları', 'Long working hours are bad for your health.', '/ˈwɜːkɪŋ ˌaʊəz/', 'collocation', ''),
  (10033, '2. IELTS B1+', 'Работа и карьера', 'flexible', 'гибкий', 'çevik', 'Flexible schedules help parents with young children.', '/ˈfleksəbl/', 'adjective', ''),
  (10034, '2. IELTS B1+', 'Работа и карьера', 'work from home', 'работать из дома', 'evdən işləmək', 'Since 2020 many people have worked from home.', '/ˌwɜːk frəm ˈhəʊm/', 'phrase', ''),
  (10035, '2. IELTS B1+', 'Работа и карьера', 'job security', 'стабильность работы, гарантия занятости', 'işin sabitliyi, iş yerinin təminatı', 'Government jobs usually offer more job security.', '/ˈdʒɒb sɪˌkjʊərəti/', 'collocation', ''),
  (10036, '2. IELTS B1+', 'Работа и карьера', 'career path', 'карьерный путь', 'karyera yolu', 'It is not easy to choose a career path at the age of seventeen.', '/kəˈrɪə pɑːθ/', 'collocation', ''),
  (10037, '2. IELTS B1+', 'Работа и карьера', 'cv', 'резюме', 'CV, tərcümeyi-hal', 'Make sure your CV is short and clear.', '/ˌsiː ˈviː/', 'noun', ''),
  (10038, '2. IELTS B1+', 'Работа и карьера', 'job vacancy', 'вакансия', 'vakansiya, boş iş yeri', 'There are few job vacancies for young graduates in small towns.', '/ˈdʒɒb ˌveɪkənsi/', 'collocation', ''),
  (10039, '2. IELTS B1+', 'Работа и карьера', 'internship', 'стажировка', 'təcrübə proqramı, staj', 'An internship gives students real work experience.', '/ˈɪntɜːnʃɪp/', 'noun', ''),
  (10040, '2. IELTS B1+', 'Работа и карьера', 'pension', 'пенсия', 'pensiya, təqaüd', 'Many elderly people cannot live on their pension alone.', '/ˈpenʃn/', 'noun', ''),
  (10041, '2. IELTS B1+', 'Работа и карьера', 'self-employed', 'самозанятый, работающий на себя', 'özü üçün işləyən, fərdi sahibkar', 'My uncle is self-employed and runs a small shop.', '/ˌself ɪmˈplɔɪd/', 'adjective', ''),
  (10042, '2. IELTS B1+', 'Работа и карьера', 'well-paid', 'хорошо оплачиваемый', 'yaxşı maaşlı', 'Engineers usually have well-paid jobs.', '/ˌwel ˈpeɪd/', 'adjective', ''),
  (10043, '2. IELTS B1+', 'Работа и карьера', 'low-paid', 'низкооплачиваемый', 'aşağı maaşlı', 'Low-paid workers often need a second job.', '/ˌləʊ ˈpeɪd/', 'adjective', ''),
  (10044, '2. IELTS B1+', 'Работа и карьера', 'job prospects', 'перспективы трудоустройства', 'iş perspektivləri', 'Learning English improves your job prospects.', '/ˈdʒɒb ˌprɒspekts/', 'collocation', ''),
  (10045, '2. IELTS B1+', 'Работа и карьера', 'teamwork', 'командная работа', 'komanda işi', 'Teamwork is an essential skill in most jobs.', '/ˈtiːmwɜːk/', 'noun', ''),
  (10046, '2. IELTS B1+', 'Работа и карьера', 'motivated', 'мотивированный', 'motivasiyalı, həvəsli', 'Staff are more motivated when their work is valued.', '/ˈməʊtɪveɪtɪd/', 'adjective', ''),
  (10047, '2. IELTS B1+', 'Работа и карьера', 'burnout', 'выгорание', 'tükənmə, peşə yorğunluğu', 'Too much stress at work can lead to burnout.', '/ˈbɜːnaʊt/', 'noun', ''),
  (10048, '2. IELTS B1+', 'Работа и карьера', 'employment', 'занятость, трудоустройство', 'məşğulluq, işlə təminat', 'Tourism creates employment in rural areas.', '/ɪmˈplɔɪmənt/', 'noun', ''),
  (10049, '2. IELTS B1+', 'Работа и карьера', 'perks', 'бонусы, льготы (на работе)', 'əlavə imtiyazlar', 'Free lunches and a gym are popular perks in IT companies.', '/pɜːks/', 'noun', ''),
  (10050, '2. IELTS B1+', 'Работа и карьера', 'be made redundant', 'быть уволенным по сокращению', 'ixtisara düşmək', 'Hundreds of workers were made redundant when the factory closed.', '/bi ˌmeɪd rɪˈdʌndənt/', 'phrase', ''),
  (10051, '2. IELTS B1+', 'Работа и карьера', 'on-the-job training', 'обучение на рабочем месте', 'iş başında təlim', 'New staff receive two weeks of on-the-job training.', '/ˌɒn ðə ˌdʒɒb ˈtreɪnɪŋ/', 'collocation', ''),
  (10052, '2. IELTS B1+', 'Работа и карьера', 'sick leave', 'больничный', 'xəstəlik məzuniyyəti', 'Employees should get paid sick leave.', '/ˈsɪk liːv/', 'collocation', ''),
  (10053, '2. IELTS B1+', 'Работа и карьера', 'maternity leave', 'декретный отпуск', 'analıq məzuniyyəti', 'She is on maternity leave until next spring.', '/məˈtɜːnəti liːv/', 'collocation', ''),
  (10054, '2. IELTS B1+', 'Работа и карьера', 'supervisor', 'руководитель, начальник', 'rəhbər, nəzarətçi', 'My supervisor gives me useful advice about my work.', '/ˈsuːpəvaɪzə/', 'noun', ''),
  (10055, '2. IELTS B1+', 'Работа и карьера', 'manual work', 'физический труд', 'fiziki əmək', 'Machines are replacing people in manual work.', '/ˌmænjuəl ˈwɜːk/', 'collocation', ''),
  (10056, '2. IELTS B1+', 'Работа и карьера', 'climb the career ladder', 'подниматься по карьерной лестнице', 'karyera pillələri ilə yüksəlmək', 'Many young people want to climb the career ladder quickly.', '/ˌklaɪm ðə kəˈrɪə ˌlædə/', 'phrase', ''),
  (10057, '2. IELTS B1+', 'Окружающая среда', 'carbon footprint', 'углеродный след', 'karbon izi', 'Flying less is one way to reduce your carbon footprint.', '/ˌkɑːbən ˈfʊtprɪnt/', 'collocation', ''),
  (10058, '2. IELTS B1+', 'Окружающая среда', 'greenhouse gases', 'парниковые газы', 'istixana qazları', 'Cars and factories produce large amounts of greenhouse gases.', '/ˈɡriːnhaʊs ˌɡæsɪz/', 'collocation', ''),
  (10059, '2. IELTS B1+', 'Окружающая среда', 'air quality', 'качество воздуха', 'havanın keyfiyyəti', 'Air quality in big cities gets worse in summer.', '/ˈeə ˌkwɒləti/', 'collocation', ''),
  (10060, '2. IELTS B1+', 'Окружающая среда', 'single-use plastic', 'одноразовый пластик', 'birdəfəlik plastik', 'Many countries have banned single-use plastic bags.', '/ˌsɪŋɡl juːs ˈplæstɪk/', 'collocation', ''),
  (10061, '2. IELTS B1+', 'Окружающая среда', 'eco-friendly', 'экологичный', 'ekoloji təmiz, ətraf mühitə zərərsiz', 'More and more shoppers choose eco-friendly products.', '/ˌiːkəʊ ˈfrendli/', 'adjective', ''),
  (10062, '2. IELTS B1+', 'Окружающая среда', 'extreme weather', 'экстремальная погода', 'ekstremal hava şəraiti', 'Extreme weather events are becoming more frequent.', '/ɪkˌstriːm ˈweðə/', 'collocation', ''),
  (10063, '2. IELTS B1+', 'Окружающая среда', 'heatwave', 'аномальная жара', 'isti dalğası', 'Last summer''s heatwave lasted for two weeks.', '/ˈhiːtweɪv/', 'noun', ''),
  (10064, '2. IELTS B1+', 'Окружающая среда', 'landfill', 'свалка, полигон отходов', 'zibil poliqonu, zibilxana', 'Most plastic waste ends up in landfill.', '/ˈlændfɪl/', 'noun', ''),
  (10065, '2. IELTS B1+', 'Окружающая среда', 'litter', 'мусор (на улице), мусорить', 'zibil, zibil atmaq', 'People who drop litter in parks should pay a fine.', '/ˈlɪtə/', 'noun', ''),
  (10066, '2. IELTS B1+', 'Окружающая среда', 'exhaust fumes', 'выхлопные газы', 'işlənmiş qazlar', 'Exhaust fumes from cars are a major cause of air pollution.', '/ɪɡˈzɔːst fjuːmz/', 'collocation', ''),
  (10067, '2. IELTS B1+', 'Окружающая среда', 'sea level', 'уровень моря', 'dəniz səviyyəsi', 'Rising sea levels are a threat to coastal cities.', '/ˈsiː ˌlevl/', 'collocation', ''),
