  (10798, '4. IELTS Academic', 'Академические прилагательные', 'fundamental', 'основной, фундаментальный', 'fundamental, köklü', 'Education is a fundamental right of every child.', '/ˌfʌndəˈmentl/', 'adjective', ''),
