  (10896, '4. IELTS Academic', 'Контраст и уступка', 'the reverse is true', 'верно обратное', 'bunun əksi doğrudur', 'Many think older people dislike technology, but often the reverse is true.', '/ðə rɪˈvɜːs ɪz truː/', 'phrase', ''),
  (10897, '4. IELTS Academic', 'Оценка (прилагательные)', 'vital', 'жизненно важный', 'həyati vacib', 'Clean water is vital for good health.', '/ˈvaɪtl/', 'adjective', ''),
