  (10901, '4. IELTS Academic', 'Оценка (прилагательные)', 'alarming', 'тревожный, пугающий', 'həyəcan verici', 'Obesity rates are rising at an alarming rate.', '/əˈlɑːmɪŋ/', 'adjective', ''),
  (10902, '4. IELTS Academic', 'Оценка (прилагательные)', 'favourable', 'благоприятный', 'əlverişli', 'The new policy received favourable reviews from teachers.', '/ˈfeɪvərəbl/', 'adjective', ''),
  (10903, '4. IELTS Academic', 'Оценка (прилагательные)', 'adverse', 'неблагоприятный, отрицательный', 'mənfi, əlverişsiz', 'Too much screen time can have adverse effects on children.', '/ˈædvɜːs/', 'adjective', ''),
