  (10944, '4. IELTS Academic', 'Количество и изменения', 'escalate', 'обостряться, возрастать', 'kəskinləşmək, artmaq', 'The conflict escalated very quickly.', '/ˈeskəleɪt/', 'verb', ''),
  (10945, '4. IELTS Academic', 'Количество и изменения', 'drastic', 'резкий, радикальный', 'kəskin, radikal', 'Drastic measures are needed to cut pollution.', '/ˈdræstɪk/', 'adjective', ''),
  (10946, '4. IELTS Academic', 'Идиомы для Speaking', 'a piece of cake', 'проще простого', 'çox asan iş', 'The reading test was a piece of cake for me.', '/ə piːs əv keɪk/', 'idiom', ''),
  (10947, '4. IELTS Academic', 'Идиомы для Speaking', 'once in a blue moon', 'очень редко', 'çox nadir hallarda', 'I eat fast food once in a blue moon.', '/wʌns ɪn ə bluː muːn/', 'idiom', ''),
